/* Mobile working surface. Business actions and server permissions are unchanged. */
function mxCall(name,...args){return E(name+'('+args.map(v=>JSON.stringify(v)).join(',')+')')}
const mxMenuCatalog=[
 ['Leads','Leads','users'],['Agenda','Task','task'],['Nasabah','Customer 360','bank'],['Peluang','Opportunity','opportunity'],['Persetujuan','Persetujuan','check'],['Monitoring','Monitoring','chart'],['Pengajuan','Pengajuan','file'],['Target & Kinerja','Target & Kinerja','chart'],['Laporan','Laporan','chart'],['Notifikasi','Notifikasi','bell'],['Absen','Riwayat absensi','task'],['Lokasi Tim','Lokasi & Journey','users'],['Member','Member','users'],['Pengaturan','Pengaturan','settings'],['Kesiapan POC','Kesiapan POC','check']
];
function mxPrimaryRoutes(role){return ({AO:['Leads','Agenda','Nasabah','Peluang'],SPV:['Persetujuan','Agenda','Peluang','Nasabah'],'Kepala Kantor':['Monitoring','Target & Kinerja','Peluang','Laporan'],'Manajemen Pusat':['Monitoring','Target & Kinerja','Laporan','Nasabah'],Superadmin:['Member','Pengaturan','Kesiapan POC','Monitoring']})[role]||['Leads','Agenda','Nasabah','Peluang']}
function mxAllowedMenu(role){return mxMenuCatalog.filter(([route])=>!(['Member','Pengaturan'].includes(route)&&role!=='Superadmin')&&!(route==='Kesiapan POC'&&role==='AO')&&!(route==='Persetujuan'&&!['AO','SPV','Superadmin'].includes(role)))}
function mxMenuButton(item){const [route,label,icon]=item;return '<button type="button" onclick="'+mxCall('rdGo',route)+'">'+mobileIcon(icon)+'<span>'+E(label)+'</span></button>'}
function mxPriorityRows(data,role){const keys=role==='SPV'?['approvals','corrections','escalations','overdue']:['overdue','today','leadSla','noNext'];const seen=new Set(),rows=[];for(const key of keys)for(const record of data.records[key]||[]){const id=record.kind+':'+record.id;if(seen.has(id))continue;if(record.kind==='task'&&['Selesai','Dibatalkan'].includes(record.stage))continue;seen.add(id);rows.push(record)}return rows.slice(0,3)}
function mxHomeMetrics(d,role){const s=d.summary;if(role==='Superadmin'){const a=d.administration;return [['Member aktif',a.activeMembers,'Kelola dari HQ Renon','route','Member'],['Konsistensi data',a.checks.errors.length,'Temuan pemeriksaan','route','Kesiapan POC']]}
 if(role==='SPV')return [['Persetujuan',s.approvals,'Kunjungan menunggu','list','approvals'],['Eskalasi SLA',s.escalations,'Prioritas pengawasan','list','escalations'],['Task overdue',s.overdue,'Perlu tindak lanjut','list','overdue'],['Koreksi data',s.corrections,'Perlu keputusan','list','corrections']];
 if(role==='AO')return [['Task hari ini',s.today,s.todayDone+' selesai','list','today'],['Task overdue',s.overdue,'Perlu ditangani','list','overdue'],['SLA Lead',s.leadSla,'Melewati batas waktu','list','leadSla'],['Opportunity aktif',s.active,rdMoney(s.pipeline),'list','active']];
 return [['Pipeline aktif',s.active,rdMoney(s.pipeline),'list','active'],['Task overdue',s.overdue,'Beban kerja tim','list','overdue'],['Customer',s.customers,'Dalam cakupan akses','list','customers'],['SLA Lead',s.leadSla,'Perlu perhatian tim','list','leadSla']];}
function mobileRoleHome(){
 const role=authUser.role,allowed=mxAllowedMenu(role),primaryRoutes=mxPrimaryRoutes(role),primary=primaryRoutes.map(route=>allowed.find(m=>m[0]===route)).filter(Boolean),other=allowed.filter(m=>!primaryRoutes.includes(m[0])),entry=roleDashCache.get(rdKey()),d=entry?.data;
 const greeting='<section class="mx-home-heading"><div><p>'+E(role)+' · '+E(activeBranch.replace('BPD BALI ',''))+'</p><h1>Halo, '+E(authUser.name)+'</h1></div><button type="button" aria-label="Buka profil pengguna" onclick="go(\'Profil User\')">'+E(authUser.name.split(' ').slice(0,2).map(x=>x[0]).join(''))+'</button></section>';
 const attendance=typeof homeAttendanceHero==='function'?homeAttendanceHero():'';
 const stats=d?'<section class="mx-home-metrics" aria-label="Ringkasan sesuai role">'+mxHomeMetrics(d,role).map(([label,value,note,kind,arg])=>'<button type="button" onclick="'+mxCall(kind==='route'?'rdGo':'rdList',arg)+'"><span>'+E(label)+'</span><strong>'+E(value)+'</strong><small>'+E(note)+'</small></button>').join('')+'</section>':'<div class="mx-home-loading" role="status">'+E(entry?.error||'Memuat pekerjaan Anda…')+(entry?.error?'<button type="button" onclick="rdLoad(true)">Coba lagi</button>':'')+'</div>';
 const menus='<section class="mx-workspace"><div class="mx-section-heading"><h2>Menu kerja</h2><span>'+E(role)+'</span></div><div class="mx-menu-grid">'+primary.map(mxMenuButton).join('')+'</div><details class="mx-other-menu"><summary>Semua menu workspace</summary><div class="mx-menu-grid">'+other.map(mxMenuButton).join('')+'</div></details></section>';
 const rows=d?mxPriorityRows(d,role):[],priorities=d&&['AO','SPV'].includes(role)?'<section class="mx-priorities"><div class="mx-section-heading"><h2>'+E(role==='SPV'?'Perlu keputusan':'Prioritas saya')+'</h2><button type="button" onclick="go(\'Monitoring\')">Lihat semua</button></div><div class="rd-records">'+(rows.map(rdRecord).join('')||'<p class="mx-empty">Tidak ada prioritas tertunda. Buka Task untuk melihat jadwal lengkap.</p>')+'</div></section>':'';
 const monitor='<button type="button" class="mx-monitor-link" onclick="go(\'Monitoring\')"><span><strong>Monitoring lengkap</strong><small>Filter kantor/AO, pipeline dan target sesuai akses</small></span>'+mobileIcon('chart')+'</button>';
 return '<div class="mx-home">'+greeting+attendance+stats+menus+priorities+monitor+(d?'<p class="mx-update">Data dummy · '+E(fmt(d.at))+' WITA <button type="button" onclick="rdLoad(true)">Perbarui</button></p>':'')+'</div>';
}
function mxProfileScreen(){
 const user=authUser;if(!user)return '';
 const facts=[['Nama lengkap',user.name],['User ID',user.userId||user.id],['Role',user.role],['Kantor penempatan',user.homeBranch||activeBranch],['Kantor aktif',activeBranch],['Zona waktu','WITA · UTC+08']];
 return '<div class="mx-profile"><section class="mx-profile-hero"><span class="mx-profile-avatar">'+E(user.name.split(' ').slice(0,2).map(x=>x[0]).join(''))+'</span><div><h1>'+E(user.name)+'</h1><p>'+E(user.role)+'</p><small>'+E(user.homeBranch||activeBranch)+'</small></div></section><section class="panel mx-profile-info"><h2>Informasi pengguna</h2><dl class="mx-profile-facts">'+facts.map(([label,value])=>'<div class="mx-profile-row"><dt>'+E(label)+'</dt><dd>'+E(value||'Belum ditetapkan')+'</dd></div>').join('')+'</dl></section><section class="mx-profile-actions" aria-label="Pengaturan akun"><button type="button" onclick="openBranchSelection()">Ganti Cabang</button><button type="button" onclick="changeOwnPassword()">Ubah password</button><button type="button" onclick="applicationInfo()">Informasi aplikasi</button><button type="button" class="mx-logout" onclick="logoutConnected()">Keluar</button></section></div>';
}
// Header avatar and Home avatar share the full user-profile route.
openAccount=function(){if(!authUser)return;document.querySelector('#modal')?.close();go('Profil User');};
function mxClearSearch(){const input=document.querySelector('#app .searchbox input');if(!input)return;input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));queueMicrotask(()=>document.querySelector('#app .searchbox input')?.focus())}
function mxCloseFilter(){const panel=document.querySelector('#app .compact-advanced');if(panel){panel.open=false;if(typeof compactFilterOpen!=='undefined')compactFilterOpen[compactListKey()]=false;panel.querySelector('summary')?.focus()}}
function mxLabelChips(app){app.querySelectorAll('.rangechips,.tabs,.recordtabs,.c360-tabs').forEach(group=>{const active=group.querySelector('[aria-pressed="true"],.active,.primary');if(!active)return;const left=active.offsetLeft,right=left+active.offsetWidth;if(left<group.scrollLeft||right>group.scrollLeft+group.clientWidth)group.scrollLeft=Math.max(0,left-12);});}
function mxDecorate(){
 if(!mobile)return;const app=document.querySelector('#app');if(!app)return;
 const input=app.querySelector('.searchbox input');if(input){const box=input.closest('.searchbox');box.classList.add('mx-search');if(!box.querySelector('.mx-clear-search')){const clear=document.createElement('button');clear.type='button';clear.className='mx-clear-search';clear.setAttribute('aria-label','Hapus pencarian');clear.textContent='×';clear.onclick=mxClearSearch;box.append(clear)}box.querySelector('.mx-clear-search').hidden=!input.value;}
 const filter=app.querySelector('.compact-advanced-body');if(filter&&!filter.querySelector('.mx-filter-done')){const done=document.createElement('button');done.type='button';done.className='mx-filter-done';done.textContent='Lihat hasil filter';done.onclick=mxCloseFilter;filter.append(done)}
 app.querySelectorAll('.scrolltable').forEach(wrapper=>{if(wrapper.previousElementSibling?.classList.contains('mx-table-hint'))return;const label=document.createElement('p');label.className='mx-table-hint';label.textContent='Geser tabel untuk melihat kolom lainnya';wrapper.before(label);wrapper.setAttribute('tabindex','0');wrapper.setAttribute('aria-label','Tabel data, dapat digeser horizontal')});
 mxLabelChips(app);
 app.querySelectorAll('.board,.lead-pipeline-board').forEach(board=>{if(board.dataset.mxBound)return;board.dataset.mxBound='true';const key=authUser?.id+'|'+activeBranch+'|'+view;board.scrollLeft=mxBoardPositions.get(key)||0;board.addEventListener('scroll',()=>mxBoardPositions.set(key,board.scrollLeft),{passive:true})});
}
const mxBoardPositions=new Map();
let mxPreviousRoute='';
function mxHomeContext(){if(view==='Home'&&mxPreviousRoute!=='Home'){if(typeof roleDashOffice!=='undefined')roleDashOffice='';if(typeof roleDashOwner!=='undefined')roleDashOwner='';if(typeof roleDashQueue!=='undefined')roleDashQueue='';}mxPreviousRoute=view;}
const mxContentBefore=renderContent;
renderContent=function(){mxHomeContext();const result=mxContentBefore.apply(this,arguments);if(view==='Profil User'&&authUser){const app=document.querySelector('#app');if(app)app.innerHTML=mxProfileScreen();}mxDecorate();return result};
function mxViewport(){const viewport=window.visualViewport;if(!viewport)return;document.documentElement.style.setProperty('--mx-viewport-height',Math.round(viewport.height)+'px');document.documentElement.style.setProperty('--mx-viewport-top',Math.round(viewport.offsetTop)+'px');const modal=document.querySelector('#modal');document.body.classList.toggle('mx-keyboard-open',!!modal?.open&&window.innerHeight-viewport.height>140);}
window.visualViewport?.addEventListener('resize',mxViewport);window.addEventListener('orientationchange',mxViewport);
document.addEventListener('focusin',e=>{if(e.target.matches?.('input,textarea,select'))mxViewport()});document.addEventListener('close',mxViewport,true);
mxViewport();
if(typeof authUser!=='undefined'&&authUser&&!choosingBranch)renderContent();
